const baccaratx=function(){const i={h:0,d:1,c:2,s:3},n=n=>{const t=n.replaceAll(" ","");return{rank:t.slice(0,-1)-1,suit:i[t.slice(-1)]}},t=/[1-9][hscd]|1[0-3][hscd]/;return{submit:function(i){i.preventDefault();const r=$("#cards").val().split(",");if(r!=""&&r.some(n=>!t.test(n))){alert(`Result cards is invalid`);return}const e=r.map(t=>n(t)),f=[],u=+$("#cutCardIndex").val();if(u&&u<0){alert(`Cut card index is invalid`);return}if($("#EnableMultiplier").val()==="true")for(let i=0;i<8;i++){const r=$(`#cards${i}`).val(),u=+$(`#multiplier${i}`).val();if(r&&u&&t.test(r))f.push({...n(r),value:u});else{alert(`Lucky card #${i+1} is invalid`);return}}const o={GameConfigName:$("#GameConfigName").val(),displayName:$("#GameConfigName").val(),result:{cards:e,luckyCards:f,cutCardIndex:u}};$.ajax({type:"POST",url:"SetBaccaratXResult",data:o,dataType:"html",success:function(n){$("#modal").modal("show");$(".modal-body").html(n?"Successful":"Internal Server Error")}})}}}();